import{_ as a,c as t,o as i,ag as o}from"./chunks/framework.CQuhCYrb.js";const p=JSON.parse('{"title":"VirtualBox Guide","description":"","frontmatter":{"title":"VirtualBox Guide"},"headers":[],"relativePath":"general/virtualbox-guide.md","filePath":"general/virtualbox-guide.md","lastUpdated":null}'),l={name:"general/virtualbox-guide.md"};function r(n,e,h,c,s,d){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="virtualbox-guide" tabindex="-1">VirtualBox Guide <a class="header-anchor" href="#virtualbox-guide" aria-label="Permalink to &quot;VirtualBox Guide&quot;">​</a></h1><h3 id="what-is-virtualbox" tabindex="-1">What is VirtualBox <a class="header-anchor" href="#what-is-virtualbox" aria-label="Permalink to &quot;What is VirtualBox&quot;">​</a></h3><p>Return to <a href="/general/dfp-guide.html">Guide</a> • Return to <a href="/general/virtual-environments.html">Environment</a></p><p>VirtualBox is a powerful x86 and AMD64/Intel64 virtualization product for enterprise and home use. It is an extremely feature-rich, high-performance product for enterprise customers and the only professional solution that is freely available as Open-Source Software under the terms of the GNU General Public License (GPL) version 2. See “About VirtualBox” for an introduction.</p><p><strong>NOTE:</strong> VirtualBox does not work well with ARM-based computers like the Apple Silicon MacBooks.</p><p>VirtualBox is actively developed with frequent releases and has an ever-growing list of features, supported guest operating systems, and platforms it runs on. VirtualBox is a community effort backed by a dedicated company: everyone is encouraged to contribute, while Oracle ensures the product always meets professional quality criteria. [</p><h3 id="why-you-should-use-virtualbox" tabindex="-1">Why You Should Use VirtualBox <a class="header-anchor" href="#why-you-should-use-virtualbox" aria-label="Permalink to &quot;Why You Should Use VirtualBox&quot;">​</a></h3><p>VirtualBox is Free Open-Source Software with active support and a large community. Despite its challenges, VirtualBox provides all “paid” features for other virtualization software.</p><p>Unlike trial or pirated software, VirtualBox receives timely security updates and patches.</p><h3 id="installing-virtualbox" tabindex="-1">Installing VirtualBox <a class="header-anchor" href="#installing-virtualbox" aria-label="Permalink to &quot;Installing VirtualBox&quot;">​</a></h3><ol><li><a href="https://www.virtualbox.org/wiki/Downloads" target="_blank" rel="noreferrer">Download</a> the latest VirtualBox Application.</li></ol><h2 id="install-the-downloaded-virtualbox-application" tabindex="-1">Install the downloaded VirtualBox Application. <a class="header-anchor" href="#install-the-downloaded-virtualbox-application" aria-label="Permalink to &quot;Install the downloaded VirtualBox Application.&quot;">​</a></h2><ol><li><a href="https://download.virtualbox.org/virtualbox/6.1.38/Oracle_VM_VirtualBox_Extension_Pack-6.1.38.vbox-extpack" target="_blank" rel="noreferrer">Download</a> the latest VirtualBox extension pack.</li></ol><h2 id="install-the-downloaded-extension-pack-by-double-clicking-it" tabindex="-1">Install the downloaded extension pack by double-clicking it. <a class="header-anchor" href="#install-the-downloaded-extension-pack-by-double-clicking-it" aria-label="Permalink to &quot;Install the downloaded extension pack by double-clicking it.&quot;">​</a></h2><h2 id="download-the-operating-system-iso" tabindex="-1">Download the Operating System (ISO). <a class="header-anchor" href="#download-the-operating-system-iso" aria-label="Permalink to &quot;Download the Operating System (ISO).&quot;">​</a></h2><h2 id="configure-virtualbox" tabindex="-1">Configure VirtualBox. <a class="header-anchor" href="#configure-virtualbox" aria-label="Permalink to &quot;Configure VirtualBox.&quot;">​</a></h2><h3 id="virtualbox-7-may-have-errors-that-randomly-require-you-to-unselect-the-audio-from-the-virtual-machine-settings" tabindex="-1">VirtualBox 7 may have errors that randomly require you to unselect the audio from the virtual machine settings. <a class="header-anchor" href="#virtualbox-7-may-have-errors-that-randomly-require-you-to-unselect-the-audio-from-the-virtual-machine-settings" aria-label="Permalink to &quot;VirtualBox 7 may have errors that randomly require you to unselect the audio from the virtual machine settings.&quot;">​</a></h3><ol><li><a href="/general/virtualbox-guide.html">ISO</a></li></ol><h3 id="download-iso" tabindex="-1">Download ISO <a class="header-anchor" href="#download-iso" aria-label="Permalink to &quot;Download ISO&quot;">​</a></h3><p>An ISO is an operating system file. You’ll use it to build your virtual computer, the operating system inside your virtual machine.</p><h2 id="download-an-iso-such-as" tabindex="-1">Download an ISO such as: <a class="header-anchor" href="#download-an-iso-such-as" aria-label="Permalink to &quot;Download an ISO such as:&quot;">​</a></h2><ol><li><p><a href="https://www.linuxmint.com/download.php" target="_blank" rel="noreferrer">Linux Mint</a> (Simple and Easy to Use)</p></li><li><p><a href="https://pop.system76.com" target="_blank" rel="noreferrer">Pop!_OS</a> (Simple and for Gaming)</p></li><li><p><a href="https://www.kali.org/get-kali/#kali-platforms" target="_blank" rel="noreferrer">Kali</a> (Red Team, Purple Team, Research, RF)</p></li></ol><h3 id="vm-images-ready-to-run" tabindex="-1"><a href="https://www.kali.org/get-kali/#kali-installer-images" target="_blank" rel="noreferrer">VM images ready to run</a> <a class="header-anchor" href="#vm-images-ready-to-run" aria-label="Permalink to &quot;[VM images ready to run](https://www.kali.org/get-kali/#kali-installer-images)&quot;">​</a></h3><ol><li><p>[(RF and SDR)</p></li><li><p><a href="/radio/dragonos.html">https://ubuntu.com/download/desktop Ubuntu</a>: This is the most used version but has some slight privacy concerns. To resolve this, don’t opt-in to send your data.</p></li><li><p><a href="https://archlinux.org/download/" target="_blank" rel="noreferrer">Arch</a>: <a href="https://wiki.archlinux.org/title/Installation_guide" target="_blank" rel="noreferrer">Installation Guide</a></p></li></ol><h2 id="remember-where-you-download-this-iso-to-as-you-ll-need-to-find-it-when-creating-a-vm" tabindex="-1">Remember where you download this ISO to, as you’ll need to find it when creating a VM. <a class="header-anchor" href="#remember-where-you-download-this-iso-to-as-you-ll-need-to-find-it-when-creating-a-vm" aria-label="Permalink to &quot;Remember where you download this ISO to, as you’ll need to find it when creating a VM.&quot;">​</a></h2><h3 id="using-virtualbox" tabindex="-1">Using VirtualBox <a class="header-anchor" href="#using-virtualbox" aria-label="Permalink to &quot;Using VirtualBox&quot;">​</a></h3><h3 id="import-virtual-machine-appliance" tabindex="-1">Import Virtual Machine (Appliance) <a class="header-anchor" href="#import-virtual-machine-appliance" aria-label="Permalink to &quot;Import Virtual Machine (Appliance)&quot;">​</a></h3><p>To import a pre-built Virtual Machine, also known as an Appliance, follow these steps:</p><h2 id="download-the-virtual-machine-appliance-file-usually-distributed-as-an-ova-or-ovf-file" tabindex="-1">Download the Virtual Machine (Appliance) file, usually distributed as an OVA or OVF file. <a class="header-anchor" href="#download-the-virtual-machine-appliance-file-usually-distributed-as-an-ova-or-ovf-file" aria-label="Permalink to &quot;Download the Virtual Machine (Appliance) file, usually distributed as an OVA or OVF file.&quot;">​</a></h2><h2 id="open-virtualbox-and-go-to-file-→-import-appliance" tabindex="-1">Open VirtualBox and go to File → Import Appliance. <a class="header-anchor" href="#open-virtualbox-and-go-to-file-→-import-appliance" aria-label="Permalink to &quot;Open VirtualBox and go to File → Import Appliance.&quot;">​</a></h2><h2 id="click-the-choose-button-in-the-import-appliance-dialog-and-select-the-downloaded-appliance-file" tabindex="-1">Click the “Choose” button in the Import Appliance dialog and select the downloaded Appliance file. <a class="header-anchor" href="#click-the-choose-button-in-the-import-appliance-dialog-and-select-the-downloaded-appliance-file" aria-label="Permalink to &quot;Click the “Choose” button in the Import Appliance dialog and select the downloaded Appliance file.&quot;">​</a></h2><h2 id="click-next-to-proceed-to-the-appliance-settings" tabindex="-1">Click “Next” to proceed to the Appliance settings. <a class="header-anchor" href="#click-next-to-proceed-to-the-appliance-settings" aria-label="Permalink to &quot;Click “Next” to proceed to the Appliance settings.&quot;">​</a></h2><h2 id="review-and-adjust-the-appliance-settings-as-needed-such-as-adjusting-the-amount-of-ram-or-the-number-of-cpus-allocated-to-the-virtual-machine" tabindex="-1">Review and adjust the Appliance settings as needed, such as adjusting the amount of RAM or the number of CPUs allocated to the virtual machine. <a class="header-anchor" href="#review-and-adjust-the-appliance-settings-as-needed-such-as-adjusting-the-amount-of-ram-or-the-number-of-cpus-allocated-to-the-virtual-machine" aria-label="Permalink to &quot;Review and adjust the Appliance settings as needed, such as adjusting the amount of RAM or the number of CPUs allocated to the virtual machine.&quot;">​</a></h2><h2 id="click-import-to-start-the-import-process" tabindex="-1">Click “Import” to start the import process. <a class="header-anchor" href="#click-import-to-start-the-import-process" aria-label="Permalink to &quot;Click “Import” to start the import process.&quot;">​</a></h2><h2 id="wait-for-the-import-process-to-complete" tabindex="-1">Wait for the import process to complete. <a class="header-anchor" href="#wait-for-the-import-process-to-complete" aria-label="Permalink to &quot;Wait for the import process to complete.&quot;">​</a></h2><h3 id="create-a-virtual-machine-from-iso" tabindex="-1">Create a Virtual Machine (From ISO) <a class="header-anchor" href="#create-a-virtual-machine-from-iso" aria-label="Permalink to &quot;Create a Virtual Machine (From ISO)&quot;">​</a></h3><p>To create a new virtual machine from an ISO file, follow these steps:</p><h2 id="open-virtualbox-and-click-the-new-button-to-create-a-new-virtual-machine" tabindex="-1">Open VirtualBox and click the “New” button to create a new virtual machine. <a class="header-anchor" href="#open-virtualbox-and-click-the-new-button-to-create-a-new-virtual-machine" aria-label="Permalink to &quot;Open VirtualBox and click the “New” button to create a new virtual machine.&quot;">​</a></h2><h2 id="in-the-create-virtual-machine-dialog-enter-a-name-and-select-the-operating-system-type-and-version" tabindex="-1">In the Create Virtual Machine dialog, enter a name and select the operating system type and version. <a class="header-anchor" href="#in-the-create-virtual-machine-dialog-enter-a-name-and-select-the-operating-system-type-and-version" aria-label="Permalink to &quot;In the Create Virtual Machine dialog, enter a name and select the operating system type and version.&quot;">​</a></h2><h2 id="set-the-amount-of-ram-and-the-number-of-cpus-allocated-to-the-virtual-machine" tabindex="-1">Set the amount of RAM and the number of CPUs allocated to the virtual machine. <a class="header-anchor" href="#set-the-amount-of-ram-and-the-number-of-cpus-allocated-to-the-virtual-machine" aria-label="Permalink to &quot;Set the amount of RAM and the number of CPUs allocated to the virtual machine.&quot;">​</a></h2><h2 id="in-the-hard-disk-section-select-create-a-virtual-hard-disk-now-and-click-create" tabindex="-1">In the “Hard disk” section, select “Create a virtual hard disk now” and click “Create.” <a class="header-anchor" href="#in-the-hard-disk-section-select-create-a-virtual-hard-disk-now-and-click-create" aria-label="Permalink to &quot;In the “Hard disk” section, select “Create a virtual hard disk now” and click “Create.”&quot;">​</a></h2><h2 id="select-the-hard-disk-file-type-and-click-next" tabindex="-1">Select the hard disk file type and click “Next.” <a class="header-anchor" href="#select-the-hard-disk-file-type-and-click-next" aria-label="Permalink to &quot;Select the hard disk file type and click “Next.”&quot;">​</a></h2><h2 id="select-dynamically-allocated-for-the-storage-on-the-physical-hard-disk-and-click-next" tabindex="-1">Select “Dynamically allocated” for the storage on the physical hard disk and click “Next.” <a class="header-anchor" href="#select-dynamically-allocated-for-the-storage-on-the-physical-hard-disk-and-click-next" aria-label="Permalink to &quot;Select “Dynamically allocated” for the storage on the physical hard disk and click “Next.”&quot;">​</a></h2><h2 id="set-the-virtual-hard-disk-size-and-click-create" tabindex="-1">Set the virtual hard disk size and click “Create.” <a class="header-anchor" href="#set-the-virtual-hard-disk-size-and-click-create" aria-label="Permalink to &quot;Set the virtual hard disk size and click “Create.”&quot;">​</a></h2><h2 id="select-the-storage-section-in-the-virtual-machine-settings-and-click-on-the-empty-cd-dvd-drive" tabindex="-1">Select the “Storage” section in the virtual machine settings and click on the empty CD/DVD drive. <a class="header-anchor" href="#select-the-storage-section-in-the-virtual-machine-settings-and-click-on-the-empty-cd-dvd-drive" aria-label="Permalink to &quot;Select the “Storage” section in the virtual machine settings and click on the empty CD/DVD drive.&quot;">​</a></h2><h2 id="click-the-cd-dvd-icon-in-the-attributes-section-and-select-the-iso-file-you-want-to-install" tabindex="-1">Click the CD/DVD icon in the Attributes section and select the ISO file you want to install. <a class="header-anchor" href="#click-the-cd-dvd-icon-in-the-attributes-section-and-select-the-iso-file-you-want-to-install" aria-label="Permalink to &quot;Click the CD/DVD icon in the Attributes section and select the ISO file you want to install.&quot;">​</a></h2><h2 id="start-the-virtual-machine" tabindex="-1">Start the virtual machine. <a class="header-anchor" href="#start-the-virtual-machine" aria-label="Permalink to &quot;Start the virtual machine.&quot;">​</a></h2><h3 id="export-virtual-machine-appliance" tabindex="-1">Export Virtual Machine (Appliance) <a class="header-anchor" href="#export-virtual-machine-appliance" aria-label="Permalink to &quot;Export Virtual Machine (Appliance)&quot;">​</a></h3><p>To export a virtual machine as an Appliance, follow these steps:</p><h2 id="shut-down-the-virtual-machine-that-you-want-to-export" tabindex="-1">Shut down the virtual machine that you want to export. <a class="header-anchor" href="#shut-down-the-virtual-machine-that-you-want-to-export" aria-label="Permalink to &quot;Shut down the virtual machine that you want to export.&quot;">​</a></h2><h2 id="select-the-virtual-machine-in-virtualbox-and-go-to-file-→-export-appliance" tabindex="-1">Select the virtual machine in VirtualBox and go to File → Export Appliance. <a class="header-anchor" href="#select-the-virtual-machine-in-virtualbox-and-go-to-file-→-export-appliance" aria-label="Permalink to &quot;Select the virtual machine in VirtualBox and go to File → Export Appliance.&quot;">​</a></h2><h2 id="in-the-export-appliance-dialog-select-the-virtual-machine-you-want-to-export-and-click-next" tabindex="-1">In the Export Appliance dialog, select the virtual machine you want to export and click “Next.” <a class="header-anchor" href="#in-the-export-appliance-dialog-select-the-virtual-machine-you-want-to-export-and-click-next" aria-label="Permalink to &quot;In the Export Appliance dialog, select the virtual machine you want to export and click “Next.”&quot;">​</a></h2><h2 id="choose-a-name-and-location-for-the-appliance-file-and-click-next" tabindex="-1">Choose a name and location for the Appliance file and click “Next.” <a class="header-anchor" href="#choose-a-name-and-location-for-the-appliance-file-and-click-next" aria-label="Permalink to &quot;Choose a name and location for the Appliance file and click “Next.”&quot;">​</a></h2><h2 id="select-the-file-format-for-the-appliance-usually-ova-and-click-next" tabindex="-1">Select the file format for the Appliance (usually OVA) and click “Next.” <a class="header-anchor" href="#select-the-file-format-for-the-appliance-usually-ova-and-click-next" aria-label="Permalink to &quot;Select the file format for the Appliance (usually OVA) and click “Next.”&quot;">​</a></h2><h2 id="review-the-appliance-settings-and-click-export" tabindex="-1">Review the Appliance settings and click “Export.” <a class="header-anchor" href="#review-the-appliance-settings-and-click-export" aria-label="Permalink to &quot;Review the Appliance settings and click “Export.”&quot;">​</a></h2><h2 id="wait-for-the-export-process-to-complete" tabindex="-1">Wait for the export process to complete. <a class="header-anchor" href="#wait-for-the-export-process-to-complete" aria-label="Permalink to &quot;Wait for the export process to complete.&quot;">​</a></h2><hr><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://www.virtualbox.org/" target="_blank" rel="noreferrer">VirtualBox Official Site</a></li></ul>',59)])])}const m=a(l,[["render",r]]);export{p as __pageData,m as default};
